function y = GXUKF( x, d )%% A linear measurement.%   if d is not entered y = x. Otherwise y = x(d)%--------------------------------------------------------------------------%   Form:%   y = GXUKF( x, d )%--------------------------------------------------------------------------%%   ------%   Inputs%   ------%   x         (:,1)  Input%   d         (1,1)  Indexes to states%%   -------%   Outputs%   -------%   y         (:,1)  Output%%--------------------------------------------------------------------------%--------------------------------------------------------------------------%   Copyright (c) 2006 Princeton Satellite Systems, Inc. %   All rights reserved.%--------------------------------------------------------------------------if( nargin > 1 && ~isempty(d) )  y = x(d);else  y = x;end%--------------------------------------% $Date$% $Id: ff5c342b9fe46fbdca798219b80542e362a92595 $